import {test,expect} from '@playwright/test';
import {PDFDocument,StandardFonts,rgb,degrees} from 'pdf-lib';
import fs from 'node:fs/promises';
import * as mupdf from 'mupdf';
async function fixture(rotation=0){const d=await PDFDocument.create(),p=d.addPage([595,842]),font=await d.embedFont(StandardFonts.Helvetica);p.drawText('Original editable text',{x:60,y:720,size:20,font});p.drawText('Keep this sentence',{x:60,y:650,size:14,font});p.drawRectangle({x:60,y:400,width:150,height:100,color:rgb(.2,.6,.4)});p.setRotation(degrees(rotation));return Buffer.from(await d.save());}
async function upload(page,bytes,name='example.pdf'){await page.locator('#file').setInputFiles({name,mimeType:'application/pdf',buffer:bytes});await expect(page.locator('#document')).toBeVisible();await expect(page.locator('#busy')).toBeHidden();await page.waitForTimeout(300);}
async function exported(page){await page.locator('#export').click();const event=page.waitForEvent('download');await page.locator('#downloadnow').click();const d=await event;await expect(page.locator('#busy')).toBeHidden();return fs.readFile(await d.path());}
function textOf(bytes){const d=mupdf.Document.openDocument(new Uint8Array(bytes),'application/pdf');let text='';for(let i=0;i<d.countPages();i++){const p=d.loadPage(i),t=p.toStructuredText();text+=t.asText();t.destroy();p.destroy();}d.destroy();return text;}
test('landing, demo editing, Turkish text export and undo',async({page})=>{const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('/');await expect(page.getByRole('heading',{name:/Belgenize/})).toBeVisible();await page.screenshot({path:'tests/landing.png',fullPage:true});await page.locator('#demo').click();await expect(page.locator('[data-page]')).toHaveCount(2);await page.locator('#addtext').click();await page.locator('#proptext').fill('Türkçe: ığüşöç İĞÜŞÖÇ');await page.locator('#proptext').blur();await page.locator('#undo').click();await page.locator('#redo').click();await page.screenshot({path:'tests/editor.png',fullPage:true});const bytes=await exported(page);expect(textOf(bytes)).toContain('Türkçe: ığüşöç İĞÜŞÖÇ');expect((await PDFDocument.load(bytes)).getPageCount()).toBe(2);expect(errors).toEqual([]);});
test('native text replacement truly removes original content and preserves other text',async({page})=>{await page.goto('/');await upload(page,await fixture());await page.locator('#edit').click();await page.locator('[data-native="0"]').click();await page.locator('#proptext').fill('Yeni içerik — İstanbul');await page.locator('#proptext').blur();await page.locator('#fontmode').selectOption('noto');const bytes=await exported(page),text=textOf(bytes);expect(text).toContain('Yeni içerik');expect(text).not.toContain('Original editable text');expect(text).toContain('Keep this sentence');await upload(page,bytes,'edited.pdf');await expect(page.locator('[data-page]')).toHaveCount(2);});
test('merge duplicate reorder rotate delete undo and project roundtrip',async({page})=>{await page.goto('/');await upload(page,await fixture());await upload(page,await fixture(90),'rotated.pdf');await page.locator('#duplicatepage').click();await expect(page.locator('[data-page]')).toHaveCount(3);await page.locator('[data-page="2"]').dragTo(page.locator('[data-page="0"]'));await page.locator('#rotate').click();await page.locator('#deletepage').click();await page.locator('#confirmdelete').click();await expect(page.locator('[data-page]')).toHaveCount(2);await page.locator('#undo').click();await expect(page.locator('[data-page]')).toHaveCount(3);const ev=page.waitForEvent('download');await page.locator('#project').click();const saved=await ev;const project=await fs.readFile(await saved.path());await page.reload();await page.locator('#file').setInputFiles({name:'roundtrip.ekopdf',mimeType:'application/json',buffer:project});await expect(page.locator('#busy')).toBeHidden();await expect(page.locator('[data-page]')).toHaveCount(3);expect((await PDFDocument.load(await exported(page))).getPageCount()).toBe(3);});
test('rotated native text editing and PNG export',async({page})=>{await page.goto('/');await upload(page,await fixture(90));await page.locator('#edit').click();await page.locator('[data-native="0"]').click();await page.locator('#proptext').fill('Rotated replacement');await page.locator('#proptext').blur();let bytes=await exported(page);expect(textOf(bytes)).not.toContain('Original editable text');expect(textOf(bytes)).toContain('Rotated replacement');await page.locator('#export').click();await page.locator('#exportformat').selectOption('png');const ev=page.waitForEvent('download');await page.locator('#downloadnow').click();const dl=await ev;expect(dl.suggestedFilename()).toMatch(/png.zip$/);expect((await fs.stat(await dl.path())).size).toBeGreaterThan(1000);});
test('redaction removes content, image crop, drawing, and visual signature export',async({page})=>{
await page.goto('/');await upload(page,await fixture());await page.locator('[data-tab="elements"]').click();await page.locator('[data-element="redact"]').click();const box=await page.locator('#overlay').boundingBox();await page.mouse.move(box.x+48,box.y+78);await page.mouse.down();await page.mouse.move(box.x+280,box.y+115);await page.mouse.up();let bytes=await exported(page);expect(textOf(bytes)).not.toContain('Original editable text');expect(textOf(bytes)).toContain('Keep this sentence');
await page.locator('[data-tab="draw"]').click();await page.locator('#drawtool').click();await page.mouse.move(box.x+100,box.y+300);await page.mouse.down();await page.mouse.move(box.x+200,box.y+340,{steps:12});await page.mouse.up();await page.locator('[data-tab="sign"]').click();await page.locator('#signature').click();const sb=await page.locator('#signcanvas').boundingBox();await page.mouse.move(sb.x+50,sb.y+70);await page.mouse.down();await page.mouse.move(sb.x+200,sb.y+110,{steps:10});await page.mouse.up();await page.locator('#usesign').click();await page.locator('#cropimage').click();await page.locator('#cropw').fill('600');await page.locator('#applycrop').click();bytes=await exported(page);const d=mupdf.Document.openDocument(new Uint8Array(bytes),'application/pdf'),p=d.loadPage(0),pix=p.toPixmap(mupdf.Matrix.scale(1,1),mupdf.ColorSpace.DeviceRGB,false);await fs.writeFile('tests/export-verified.png',pix.asPNG());expect(pix.getWidth()).toBe(595);pix.destroy();p.destroy();d.destroy();});
test('mobile panels and malformed project rejection',async({page})=>{await page.setViewportSize({width:390,height:844});await page.goto('/');await page.locator('#newblank').click();await page.locator('[data-tab="text"]').click();await expect(page.locator('#textbody')).toBeVisible();await page.locator('#textbody').click();await expect(page.locator('#proptext')).toBeVisible();await page.locator('#proptext').fill('Mobil düzenleme');await page.locator('#proptext').blur();await page.screenshot({path:'tests/mobile.png'});await page.locator('#file').setInputFiles({name:'bad.ekopdf',mimeType:'application/json',buffer:Buffer.from(JSON.stringify({version:1,state:{pages:[{id:'evil',w:595,h:842,rotation:0,objects:[{type:'image',src:'javascript:alert(1)'}],removed:[]}],title:'Bad'},sources:{}}))});await expect(page.locator('#toast')).toContainText('geçersiz');await expect(page.locator('#proptext')).toHaveValue('Mobil düzenleme');});

